    /**
     * Method to retrieve the Opportunity via an FindOpportunityQuery
     * @return 	query	FindOpportunityQuery
     */
    @SuppressWarnings("unused")
    public Opportunity find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Opportunity - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Opportunitys
     *
     * @param	query	FindAllOpportunityQuery 
     * @return 	List<Opportunity> 
     */
    @SuppressWarnings("unused")
    public List<Opportunity> findAll( FindAllOpportunityQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Opportunity - {0}", exc.getMessage() );
    	}
    	return null;
    }


